// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        vm.assume(amount <= address(this).balance);
        vm.deal(address(c), amount);
        uint256 beforeBalance = address(c).balance;
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        if (ok) {
            uint256 afterBalance = address(c).balance;
            assertTrue(afterBalance < beforeBalance);
        }
    }
}
